<script setup lang="ts">
const {data,pending,refresh}=await useFetch<any>('/api/winter-arc');const create=ref(false);const name=ref('Winter Arc 2026');const duration=ref(90);const startDate=ref(new Date().toLocaleDateString('en-CA'))
async function start(){await $fetch('/api/winter-arc',{method:'POST',body:{name:name.value,duration:duration.value,startDate:startDate.value}});create.value=false;await refresh()}
async function toggle(h:any){await $fetch(`/api/habits/${h.id}/completion`,{method:'POST',body:{date:new Date().toLocaleDateString('en-CA'),completed:!h.todayCompleted}});await refresh()}
</script>
<template><div><p class="text-sm font-medium text-sky-700">YOUR DAILY RHYTHM</p><div class="mt-2 flex items-end justify-between"><div><h1 class="text-3xl font-semibold">Winter Arc</h1><p class="mt-2 text-stone-500">Steady habits. Stronger days.</p></div><button v-if="!data?.challenge" class="rounded-xl bg-emerald-800 px-4 py-3 text-sm font-semibold text-white" @click="create=true">Start a challenge</button></div><div v-if="pending" class="mt-8 h-48 animate-pulse rounded-2xl bg-stone-200"/><template v-else-if="data?.challenge"><section class="mt-7 rounded-3xl bg-gradient-to-br from-slate-900 to-emerald-950 p-7 text-white"><div class="flex justify-between"><div><p class="text-sm text-white/60">ACTIVE CHALLENGE</p><h2 class="mt-2 text-2xl font-semibold">{{data.challenge.name}}</h2></div><span class="text-4xl">❄️</span></div><p class="mt-6 text-3xl font-semibold">Day {{data.challenge.day}} <span class="text-lg font-normal text-white/60">/ {{data.challenge.duration}}</span></p><div class="mt-5 h-2 rounded-full bg-white/15"><div class="h-full rounded-full bg-cyan-300" :style="{width:data.stats.challengeCompletion+'%'}"/></div><div class="mt-5 grid grid-cols-2 gap-4 sm:grid-cols-4"><div><p class="text-sm text-white/60">Current streak</p><p class="mt-1 text-xl">🔥 {{data.stats.currentStreak}} days</p></div><div><p class="text-sm text-white/60">Best streak</p><p class="mt-1 text-xl">{{data.stats.longestStreak}} days</p></div><div><p class="text-sm text-white/60">Completed days</p><p class="mt-1 text-xl">{{data.stats.completedDays}}</p></div><div><p class="text-sm text-white/60">Habits complete today</p><p class="mt-1 text-xl">{{data.stats.habitCompletion}}%</p></div></div></section><section class="mt-7"><div class="mb-4"><h2 class="text-lg font-semibold">Today's habits</h2><p class="text-sm text-stone-500">{{data.stats.todayCompleted}} / {{data.habits.length}} completed</p></div><div class="grid gap-3 sm:grid-cols-2"><button v-for="h in data.habits" :key="h.id" class="flex items-center gap-4 rounded-2xl bg-white p-4 text-left shadow-sm" @click="toggle(h)"><span class="grid size-11 place-items-center rounded-xl bg-emerald-50 text-xl">{{h.icon}}</span><span class="flex-1"><span class="block font-medium">{{h.name}}</span><span class="text-sm text-stone-500">{{h.target}} {{h.unit}}</span></span><span class="grid size-6 place-items-center rounded-full border" :class="h.todayCompleted?'border-emerald-700 bg-emerald-700 text-white':'border-stone-300'">{{h.todayCompleted?'✓':''}}</span></button></div></section></template><div v-else class="mt-7 rounded-2xl bg-white p-10 text-center"><p class="text-4xl">❄️</p><h2 class="mt-3 text-xl font-semibold">No Winter Arc challenge yet</h2><p class="mt-2 text-sm text-stone-500">Start a challenge and build your routine.</p></div><div v-if="create" class="fixed inset-0 z-50 grid place-items-center bg-black/40 p-5"><form class="w-full max-w-md rounded-2xl bg-white p-6" @submit.prevent="start"><h2 class="text-xl font-semibold">Create your challenge</h2><label class="mt-5 block text-sm">Name<input v-model="name" required class="mt-1 w-full rounded-lg border p-3"></label><label class="mt-4 block text-sm">Start date<input v-model="startDate" type="date" required class="mt-1 w-full rounded-lg border p-3"></label><label class="mt-4 block text-sm">Duration<select v-model.number="duration" class="mt-1 w-full rounded-lg border p-3"><option :value="30">30 days</option><option :value="60">60 days</option><option :value="75">75 days</option><option :value="90">90 days</option></select></label><div class="mt-6 flex justify-end gap-3"><button type="button" class="rounded-lg border px-4 py-2" @click="create=false">Cancel</button><button class="rounded-lg bg-emerald-800 px-4 py-2 font-semibold text-white">Start</button></div></form></div></div></template>
